using System.Text.RegularExpressions;

namespace PaymentAuthorization.ArchitectureTest;

// Inner layers are checked from source (project references and namespaces used),
// because framework types like File and HttpClient hide behind facade assemblies.
public sealed class LayerDependencyTests
{
    private const string Prefix = "PaymentAuthorization.";

    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics.Process",
        "Microsoft.Data", "Microsoft.EntityFrameworkCore", "Microsoft.Extensions", "Microsoft.AspNetCore",
        "Npgsql", "Dapper", "Newtonsoft",
    ];

    private static readonly string Root = FindRoot();

    [Fact]
    public void Domain_depends_on_no_other_layer()
        => AssertNoProjectReferences("Domain", []);

    [Fact]
    public void Application_depends_only_on_Domain()
        => AssertNoProjectReferences("Application", ["Domain"]);

    [Fact]
    public void Domain_uses_no_technical_namespaces()
        => AssertNoForbiddenNamespaces("Domain", ["Application", "Infrastructure"]);

    [Fact]
    public void Application_uses_no_technical_namespaces()
        => AssertNoForbiddenNamespaces("Application", ["Infrastructure"]);

    [Fact]
    public void Inner_layers_have_no_package_references()
    {
        foreach (var layer in new[] { "Domain", "Application" })
            Assert.DoesNotContain("PackageReference", File.ReadAllText(CsprojOf(layer)));
    }

    private static void AssertNoProjectReferences(string layer, string[] allowed)
    {
        var refs = Regex.Matches(File.ReadAllText(CsprojOf(layer)), @"ProjectReference\s+Include=""[^""]*?([\w.]+)\.csproj""")
            .Select(m => m.Groups[1].Value);
        var violations = refs.Where(r => !allowed.Contains(r.Replace(Prefix, ""))).ToList();
        Assert.True(violations.Count == 0, $"{layer} must not reference: {string.Join(", ", violations)}");
    }

    private static void AssertNoForbiddenNamespaces(string layer, string[] forbiddenLayers)
    {
        var forbidden = TechnicalNamespaces.Concat(forbiddenLayers.Select(l => Prefix + l)).ToArray();
        var pattern = new Regex(@"(?<![\w.])(?:" + string.Join("|", forbidden.Select(Regex.Escape)) + @")(?![\w])");
        var violations = new List<string>();
        var dir = Path.Combine(Root, "src", Prefix + layer);
        foreach (var file in Directory.EnumerateFiles(dir, "*.cs", SearchOption.AllDirectories)
                     .Where(f => !f.Contains($"{Path.DirectorySeparatorChar}obj{Path.DirectorySeparatorChar}")
                              && !f.Contains($"{Path.DirectorySeparatorChar}bin{Path.DirectorySeparatorChar}")))
        {
            var lines = File.ReadAllLines(file);
            for (var i = 0; i < lines.Length; i++)
                if (pattern.IsMatch(lines[i]))
                    violations.Add($"{Path.GetRelativePath(Root, file)}:{i + 1}: {lines[i].Trim()}");
        }
        Assert.True(violations.Count == 0, $"{layer} uses forbidden dependencies:\n{string.Join("\n", violations)}");
    }

    private static string CsprojOf(string layer)
        => Path.Combine(Root, "src", Prefix + layer, Prefix + layer + ".csproj");

    private static string FindRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "PaymentAuthorization.slnx")))
            dir = dir.Parent;
        return dir?.FullName ?? throw new InvalidOperationException("Solution root not found");
    }
}
